#include <bits/stdc++.h>
using namespace std;
int main(){for(int n=2;n<=3;n++){int d=n+1;vector<vector<int>> cfg;function<void(vector<int>)>gen=[&](vector<int>v){if(!v.empty()){for(int b=0;b<2;b++){auto w=v;w.push_back(n+b);cfg.push_back(w);}}for(int i=0;i<n;i++)if(find(v.begin(),v.end(),i)==v.end()){auto w=v;w.push_back(i);gen(w);}};gen({});int q=1;for(int i=0;i<n;i++)q*=3;vector<vector<int>>fs(q);for(int s=0;s<q;s++){vector<int>co(n);int t=s;for(int &x:co)x=t%3,t/=3;for(auto cf:cfg){int b=0;for(int i:cf){if(i>=n){b=i-n;break;}if(co[i]){b=co[i]-1;break;}}fs[s].push_back(b);}}int best=0;vector<int>ix;function<void(int)>search=[&](int begin){if(ix.size()==d){int seen=0;for(auto &f:fs){int b=0;for(int i=0;i<d;i++)b|=f[ix[i]]<<i;seen|=1<<b;}int sc=__builtin_popcount((unsigned)seen);if(sc>best){best=sc;cout<<n<<" "<<best<<": ";for(int i:ix){for(int j:cfg[i])cout<<j;cout<<" ";}cout<<endl;}return;}for(int i=begin;i<cfg.size();i++){ix.push_back(i);search(i+1);ix.pop_back();}};search(0);}}
